ALTER TABLE "app"."store_orders" DROP CONSTRAINT "store_orders_status_check";--> statement-breakpoint
ALTER TABLE "app"."store_orders" DROP CONSTRAINT "store_orders_payment_check";--> statement-breakpoint
ALTER TABLE "app"."store_orders" ADD COLUMN "refunded_minor_units" integer;--> statement-breakpoint
ALTER TABLE "app"."store_orders" ADD COLUMN "refunded_at" timestamp with time zone;--> statement-breakpoint
CREATE UNIQUE INDEX "store_orders_payment_intent_unique" ON "app"."store_orders" USING btree ("payment_intent_id") WHERE "app"."store_orders"."payment_intent_id" is not null;--> statement-breakpoint
ALTER TABLE "app"."store_orders" ADD CONSTRAINT "store_orders_refund_check" CHECK (("app"."store_orders"."status" = 'refunded' and "app"."store_orders"."refunded_minor_units" > 0 and "app"."store_orders"."refunded_at" is not null) or ("app"."store_orders"."status" <> 'refunded' and "app"."store_orders"."refunded_minor_units" is null and "app"."store_orders"."refunded_at" is null));--> statement-breakpoint
ALTER TABLE "app"."store_orders" ADD CONSTRAINT "store_orders_status_check" CHECK ("app"."store_orders"."status" in ('pending', 'paid', 'refunded'));--> statement-breakpoint
ALTER TABLE "app"."store_orders" ADD CONSTRAINT "store_orders_payment_check" CHECK (("app"."store_orders"."status" in ('paid', 'refunded') and "app"."store_orders"."checkout_session_id" is not null and "app"."store_orders"."charged_minor_units" is not null and "app"."store_orders"."charged_minor_units" >= 0 and "app"."store_orders"."charged_currency" is not null and "app"."store_orders"."paid_at" is not null) or ("app"."store_orders"."status" = 'pending' and "app"."store_orders"."payment_intent_id" is null and "app"."store_orders"."charged_minor_units" is null and "app"."store_orders"."charged_currency" is null and "app"."store_orders"."paid_at" is null));